def get_pokemon_letters_geometry(target_height=None):
    """
    Restituisce la geometria delle lettere del logo ufficiale Pokémon
    scalata all'altezza desiderata (mantenendo le proporzioni vettoriali originali 1:1).
    """
    g = wkt.loads(WKT_POKEMON_LETTERS)
    if target_height is not None:
        minx, miny, maxx, maxy = g.bounds
        h = maxy - miny
        if h > 1e-4:
            scale = target_height / h
            g = affinity.scale(g, xfact=scale, yfact=scale, origin=(0, 0))
    return g

def get_pokemon_contour_geometry(target_height=None):
    """Restituisce la sagoma di contorno ufficiale del logo Pokémon."""
    g = wkt.loads(WKT_POKEMON_CONTOUR)
    if target_height is not None:
        # Usa il fattore di scala calcolato sulle lettere (h_ref = 52.824224)
        h_ref = 52.824223999999994
        scale = target_height / h_ref
        g = affinity.scale(g, xfact=scale, yfact=scale, origin=(0, 0))
    return g
